{mat <- input[["layers/norm_data"]][,];
colnames(mat) <- input[["row_attrs/gene_names"]][];
rownames(mat) <- input[["col_attrs/cell_names"]][];
mat <- t(mat);
return(mat)}

{l <- input$ls(recursive=TRUE);
s <- l[,1][stringr::str_detect(l[,1], "col_attrs/")];
s2 <- sapply(s, FUN=function(x) {input[[x]][]});
colnames(s2) <- stringr::str_remove(colnames(s2),"col_attrs/");
meta <- tibble::column_to_rownames(as.data.frame(s2), "cell_names");
return(meta)}
